// Vite injects this at build time (see vite.config.js). Every deploy gets a
// fresh timestamp automatically — no manual version bumping needed.
const BUILD_TIME = typeof __BUILD_TIME__ !== 'undefined' ? __BUILD_TIME__ : null;
function formatBuildStamp() {
  if (!BUILD_TIME) return 'dev build';
  try {
    const d = new Date(BUILD_TIME);
    return d.toLocaleDateString([], { month: 'short', day: 'numeric' }) + ' · ' + d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  } catch (e) { return 'dev build'; }
}
