const SECTION_COLORS = ['#0170B9', '#2D9EDD', '#0B4F7A', '#5B8FB0', '#2B2E33', '#3C6E9C'];

function uid() { return Math.random().toString(36).slice(2, 10); }

function compressImage(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const maxW = 1280;
        const scale = Math.min(1, maxW / img.width);
        const canvas = document.createElement('canvas');
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        const ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.72));
      };
      img.onerror = reject;
      img.src = e.target.result;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
}

function fmtTime(ts) { return new Date(ts).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); }
function fmtDate(ts) { return new Date(ts).toLocaleDateString([], { year: 'numeric', month: 'short', day: 'numeric' }); }
function timeOfDayLabel(d) {
  const h = d.getHours();
  if (h < 5) return 'Night';
  if (h < 12) return 'Morning';
  if (h < 17) return 'Afternoon';
  if (h < 21) return 'Evening';
  return 'Night';
}

async function fetchWeather(address) {
  const prompt = `Search the web for the current weather right now at this location: ${address}. ` +
    `Once you find it, respond with exactly one line in this format and nothing else after it: ` +
    `WEATHER: <temperature in Celsius as a whole number>C, <short condition, e.g. Partly cloudy>`;
  const resp = await fetch('/api/claude', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: 1024,
      messages: [{ role: 'user', content: prompt }],
      tools: [{ type: 'web_search_20250305', name: 'web_search' }]
    })
  });
  const data = await resp.json();
  if (data.error) throw new Error(data.error.message || 'API error');
  const text = (data.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
  if (!text.trim()) throw new Error('Empty response from weather lookup');

  const tagged = text.match(/WEATHER:\s*(-?\d+)\s*°?\s*C\s*,?\s*([^\n]*)/i);
  if (tagged) return `${tagged[1]}°C${tagged[2].trim() ? ', ' + tagged[2].trim() : ''}`;

  const anyTemp = text.match(/(-?\d+)\s*°?\s*C\b/i);
  if (anyTemp) {
    const cond = text.match(/(clear|sunny|cloud|overcast|rain|storm|snow|fog|drizzle|humid|wind)[a-z\s]*/i);
    return `${anyTemp[1]}°C${cond ? ', ' + cond[0].trim() : ''}`;
  }
  throw new Error('Could not find a temperature in: "' + text.slice(0, 160) + '"');
}

const PAGE_W = 612, PAGE_H = 792, MARGIN = 48;
const CONTENT_W = PAGE_W - MARGIN * 2;

function loadScript(src) {
  return new Promise((resolve, reject) => {
    if (document.querySelector(`script[src="${src}"]`)) { resolve(); return; }
    const s = document.createElement('script');
    s.src = src; s.onload = () => resolve(); s.onerror = () => reject(new Error('Could not load PDF engine'));
    document.head.appendChild(s);
  });
}

function loadImageDims(dataUrl) {
  return new Promise(resolve => {
    const img = new Image();
    img.onload = () => resolve({ w: img.naturalWidth || 4, h: img.naturalHeight || 3 });
    img.onerror = () => resolve({ w: 4, h: 3 });
    img.src = dataUrl;
  });
}

async function buildVisitPdf(visit) {
  if (!window.jspdf) {
    await loadScript('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js');
  }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'pt', format: 'letter' });
  let y = MARGIN;

  const ensureSpace = (h) => {
    if (y + h > PAGE_H - MARGIN - 20) { doc.addPage(); y = MARGIN; }
  };

  const text = (str, x, size, opts = {}) => {
    doc.setFont('helvetica', opts.bold ? 'bold' : 'normal');
    doc.setFontSize(size);
    doc.setTextColor(opts.color || '#1A1A1A');
    const maxW = opts.maxWidth || CONTENT_W;
    const lines = doc.splitTextToSize(str || '', maxW);
    const lineH = size * 1.32;
    ensureSpace(lines.length * lineH);
    lines.forEach((line, i) => {
      doc.text(line, x, y + size * 0.9 + i * lineH, opts.align ? { align: opts.align } : undefined);
    });
    y += lines.length * lineH + (opts.marginBottom || 0);
  };

  const hr = (gap = 10) => {
    ensureSpace(gap + 1);
    y += gap * 0.4;
    doc.setDrawColor('#D8D6CE');
    doc.line(MARGIN, y, PAGE_W - MARGIN, y);
    y += gap * 0.6;
  };

  try { doc.addImage(ZZAP_LOGO, 'JPEG', PAGE_W - MARGIN - 95, MARGIN - 6, 95, 42.6); } catch (e) { /* logo optional */ }
  doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5); doc.setTextColor('#6B6F76');
  doc.text(FIRM.address, PAGE_W - MARGIN, MARGIN + 44, { align: 'right' });
  doc.text(FIRM.phone, PAGE_W - MARGIN, MARGIN + 55, { align: 'right' });
  text(`Site Visit Review ${visit.reviewNumber || 1}`, MARGIN, 20, { bold: true, marginBottom: 6 });
  text(visit.project || 'Untitled project', MARGIN, 13, { bold: true, marginBottom: 2 });
  if (visit.address) text(visit.address, MARGIN, 10.5, { color: '#6B6F76', marginBottom: 2 });
  if (visit.projectNumber) text(`Project No. ${visit.projectNumber}`, MARGIN, 10, { color: '#6B6F76', marginBottom: 4 });
  hr();

  const col2X = MARGIN + CONTENT_W / 2 + 8;
  const metaRow = (leftLabel, leftVal, rightLabel, rightVal) => {
    const startY = y;
    text(`${leftLabel}: ${leftVal || '—'}`, MARGIN, 10.5, { maxWidth: CONTENT_W / 2 - 16 });
    const afterLeftY = y;
    y = startY;
    text(`${rightLabel}: ${rightVal || '—'}`, col2X, 10.5, { maxWidth: CONTENT_W / 2 - 16 });
    y = Math.max(y, afterLeftY) + 4;
  };
  const reviewDateStr = `${fmtDate(visit.date)}${visit.timeLabel ? ' ' + visit.timeLabel.split(' (')[0] : ''}`;
  metaRow('Review date', reviewDateStr, 'Issue date', visit.issueDate);
  metaRow('Weather', visit.weather, 'General Contractor', visit.generalContractor);
  metaRow('Author', visit.visitor, 'Attendees', visit.attendees);
  hr();

  text('Disclaimer:', MARGIN, 10.5, { bold: true, marginBottom: 2 });
  text(visit.disclaimer, MARGIN, 9.5, { color: '#6B6F76', marginBottom: 6 });
  hr();

  const activeSections = visit.sections.filter(s => s.entries.length > 0);
  if (!activeSections.length) text('No photos captured yet.', MARGIN, 11, { color: '#6B6F76' });

  for (let sIdx = 0; sIdx < activeSections.length; sIdx++) {
    const s = activeSections[sIdx];
    const sectionNum = sIdx + 1;

    ensureSpace(24);
    text(`${sectionNum} ${s.name}`, MARGIN, 14, { bold: true, marginBottom: 4 });

    if ((s.subheading || '').trim()) {
      ensureSpace(18);
      doc.setFont('helvetica', 'bold'); doc.setFontSize(11); doc.setTextColor('#1A1A1A');
      doc.text(`${sectionNum}.1 ${s.subheading}`, MARGIN, y + 9);
      y += 18;
    }

    for (let i = 0; i < s.entries.length; i++) {
      const en = s.entries[i];
      const dims = await Promise.all(en.photos.map(p => loadImageDims(p)));

      // caption line, full width
      const numStr = `${i + 1}. `;
      doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5); doc.setTextColor('#1A1A1A');
      const numW = doc.getTextWidth(numStr);
      const lines = doc.splitTextToSize(en.caption || '', CONTENT_W - numW);
      const lineH = 9.5 * 1.35;
      ensureSpace(lines.length * lineH + 4);
      doc.text(numStr, MARGIN, y + 9);
      lines.forEach((line, li) => doc.text(line, MARGIN + numW, y + 9 + li * lineH));
      y += lines.length * lineH + 8;

      // photo row — sized for print legibility, aspect preserved, wraps as needed
      const gap = 10;
      const maxRowH = 220;
      const targetW = en.photos.length === 1 ? Math.min(320, CONTENT_W) : Math.min(230, (CONTENT_W - gap * 2) / Math.min(en.photos.length, 3));
      let rowX = MARGIN, rowStartY = y, rowMaxH = 0, startedRow = false;
      for (let pi = 0; pi < en.photos.length; pi++) {
        const { w, h } = dims[pi];
        let w0 = targetW, h0 = targetW * (h / w);
        if (h0 > maxRowH) { h0 = maxRowH; w0 = maxRowH * (w / h); }
        if (startedRow && rowX + w0 > PAGE_W - MARGIN) {
          y = rowStartY + rowMaxH + gap;
          rowX = MARGIN; rowStartY = y; rowMaxH = 0; startedRow = false;
        }
        if (!startedRow) { ensureSpace(maxRowH + gap); rowStartY = y; }
        try { doc.addImage(en.photos[pi], 'JPEG', rowX, rowStartY, w0, h0); } catch (e) { /* skip bad image */ }
        rowX += w0 + gap;
        rowMaxH = Math.max(rowMaxH, h0);
        startedRow = true;
      }
      if (startedRow) y = rowStartY + rowMaxH + gap;
      y += 6;
    }
    y += 10;
  }

  const pageCount = doc.internal.getNumberOfPages();
  for (let p = 1; p <= pageCount; p++) {
    doc.setPage(p);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor('#6B6F76');
    doc.text(`Page ${p} of ${pageCount}`, PAGE_W - MARGIN, PAGE_H - 24, { align: 'right' });
    doc.text(FIRM.name, MARGIN, PAGE_H - 34);
    doc.text(FIRM.address, MARGIN, PAGE_H - 24);
    doc.text(FIRM.phone, MARGIN, PAGE_H - 14);
  }

  return doc.output('blob');
}

async function buildChecklistPdf(visit, checklistLibrary) {
  if (!window.jspdf) {
    await loadScript('https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js');
  }
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF({ unit: 'pt', format: 'letter' });
  let y = MARGIN;

  const ensureSpace = (h) => {
    if (y + h > PAGE_H - MARGIN - 20) { doc.addPage(); y = MARGIN; }
  };
  const text = (str, x, size, opts = {}) => {
    doc.setFont('helvetica', opts.bold ? 'bold' : 'normal');
    doc.setFontSize(size);
    doc.setTextColor(opts.color || '#1A1A1A');
    const maxW = opts.maxWidth || CONTENT_W;
    const lines = doc.splitTextToSize(str || '', maxW);
    const lineH = size * 1.32;
    ensureSpace(lines.length * lineH);
    lines.forEach((line, i) => doc.text(line, x, y + size * 0.9 + i * lineH));
    y += lines.length * lineH + (opts.marginBottom || 0);
  };
  const hr = (gap = 10) => {
    ensureSpace(gap + 1);
    y += gap * 0.4;
    doc.setDrawColor('#D8D6CE');
    doc.line(MARGIN, y, PAGE_W - MARGIN, y);
    y += gap * 0.6;
  };

  try { doc.addImage(ZZAP_LOGO, 'JPEG', PAGE_W - MARGIN - 95, MARGIN - 6, 95, 42.6); } catch (e) { /* logo optional */ }
  doc.setFont('helvetica', 'normal'); doc.setFontSize(8.5); doc.setTextColor('#6B6F76');
  doc.text(FIRM.address, PAGE_W - MARGIN, MARGIN + 44, { align: 'right' });
  doc.text(FIRM.phone, PAGE_W - MARGIN, MARGIN + 55, { align: 'right' });

  text('Field Checklist', MARGIN, 20, { bold: true, marginBottom: 6 });
  text(visit.project || 'Untitled project', MARGIN, 13, { bold: true, marginBottom: 2 });
  if (visit.address) text(visit.address, MARGIN, 10.5, { color: '#6B6F76', marginBottom: 2 });
  text(`${fmtDate(visit.date)}${visit.timeLabel ? ' · ' + visit.timeLabel : ''}${visit.visitor ? ' · ' + visit.visitor : ''}`, MARGIN, 10, { color: '#6B6F76', marginBottom: 6 });
  hr();

  const checked = visit.checklistChecked || {};
  const activePhases = checklistLibrary
    .map(phase => ({ phase, phaseChecked: phase.items.filter(it => checked[it.id]).length }))
    .filter(({ phase, phaseChecked }) => phase.items.length > 0 && phaseChecked > 0);

  let totalItems = 0, totalChecked = 0;

  if (!activePhases.length) {
    text('No checklist items have been checked yet.', MARGIN, 11, { color: '#6B6F76' });
  }

  for (const { phase, phaseChecked } of activePhases) {
    ensureSpace(20);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(12.5); doc.setTextColor('#1A1A1A');
    doc.text(phase.name, MARGIN, y + 10);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5); doc.setTextColor('#6B6F76');
    doc.text(`${phaseChecked} / ${phase.items.length}`, PAGE_W - MARGIN, y + 10, { align: 'right' });
    y += 20;

    for (const item of phase.items) {
      totalItems++;
      const isChecked = !!checked[item.id];
      if (isChecked) totalChecked++;
      const boxSize = 9;
      const lines = doc.splitTextToSize(item.text, CONTENT_W - boxSize - 10);
      const lineH = 9.5 * 1.35;
      ensureSpace(lines.length * lineH + 4);
      doc.setDrawColor(isChecked ? '#2F7D52' : '#8A8D91');
      doc.setFillColor(isChecked ? '#2F7D52' : '#FFFFFF');
      doc.rect(MARGIN, y + 1, boxSize, boxSize, isChecked ? 'FD' : 'D');
      if (isChecked) {
        doc.setDrawColor('#FFFFFF'); doc.setLineWidth(1.1);
        doc.line(MARGIN + 1.8, y + 5.2, MARGIN + 3.6, y + 7.5);
        doc.line(MARGIN + 3.6, y + 7.5, MARGIN + 7.3, y + 2.2);
        doc.setLineWidth(0.6);
      }
      doc.setFont('helvetica', 'normal'); doc.setFontSize(9.5);
      doc.setTextColor(isChecked ? '#6B6F76' : '#1A1A1A');
      lines.forEach((line, li) => doc.text(line, MARGIN + boxSize + 8, y + 9 + li * lineH));
      y += lines.length * lineH + 4;
    }
    y += 10;
  }

  const pageCount = doc.internal.getNumberOfPages();
  for (let p = 1; p <= pageCount; p++) {
    doc.setPage(p);
    doc.setFont('helvetica', 'normal'); doc.setFontSize(8); doc.setTextColor('#6B6F76');
    doc.text(`Page ${p} of ${pageCount}`, PAGE_W - MARGIN, PAGE_H - 24, { align: 'right' });
    doc.text(`${FIRM.name} · Field Checklist · ${totalChecked}/${totalItems} reviewed`, MARGIN, PAGE_H - 24);
  }

  return doc.output('blob');
}

async function checkNotesQuality(entries) {
  if (!entries.length) return {};
  const list = entries.map(e => `[${e.id}] ${e.caption}`).join('\n');
  const prompt = `These are field notes dictated via speech-to-text during a construction site inspection. ` +
    `Some may be garbled, cut off mid-thought, or too vague to be useful in a formal report. ` +
    `For each note that has a real problem, respond with one line in exactly this format:\n` +
    `ID:<id>|ISSUE:<very short reason, 3-6 words>|FIX:<a clear, concise, professional rewrite preserving the original meaning — never invent details that weren't said>\n` +
    `Skip notes that are already clear, even if brief or informal. If every note is fine, respond with exactly: OK\n` +
    `Do not include any other text.\n\nNotes:\n${list}`;
  const resp = await fetch('/api/claude', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'claude-sonnet-4-6',
      max_tokens: Math.min(4000, 300 + entries.length * 120),
      messages: [{ role: 'user', content: prompt }]
    })
  });
  const data = await resp.json();
  if (data.error) throw new Error(data.error.message || 'API error');
  const text = (data.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
  const result = {};
  text.split('\n').forEach(line => {
    const m = line.match(/^ID:(\S+)\|ISSUE:(.*?)\|FIX:(.*)$/i);
    if (m) result[m[1]] = { issue: m[2].trim(), fix: m[3].trim() };
  });
  return result;
}

